  const invalidConnection: api.IConnection = { host: connection.host };
  await TestValidator.httpError(
    "invalid temporary access data rejected",
    [400, 401, 403],
    async () => {
      await api.functional.erpHrmTime.auth.guest.join(invalidConnection, {
        body: {
          href,
          referrer,
          email,
