    firstUpdated.description,
    firstDescription,
  );
  TestValidator.equals(
    "organization logo updated",
    firstUpdated.logoImageUrl,
    firstLogoImageUrl,
  );
  const secondDescription = RandomGenerator.paragraph({ sentences: 3 });
