    async () => {
      await api.functional.erpHrmTime.member.organizations.patch(
        nonOwnerOrgConnection,
        {
          body: {
            name: `${firstName} forbidden`,
          } satisfies IErpHrmTimeOrganization.IUpdate,
        },
      );
    },
  );
  const afterForbiddenAttempt =
    await api.functional.erpHrmTime.member.organizations.patch(
      ownerOrgConnection,
      {
        body: {
          name: firstUpdated.name,
        } satisfies IErpHrmTimeOrganization.IUpdate,
