  TestValidator.equals(
    "history remains unchanged across reads",
    secondResponse.pagination,
    firstResponse.pagination,
  );
  TestValidator.equals(
    "history data remains unchanged across reads",
    secondResponse.data,
    firstResponse.data,
  );
}

