      id: input.id,
      email: "",
      status,
      member: input.member ? ({} as IErpHrmTimeMember.ISummary) : undefined,
      createdAt: input.created_at.toISOString(),
      updatedAt: input.updated_at.toISOString(),
    };
  }
}

