export async function postErpHrmTimeMemberTimesheetsTimesheetIdReject(props: {
  member: MemberPayload;
  timesheetId: string & tags.Format<"uuid">;
  body: IErpHrmTimeTimesheet.IReject;
}): Promise<IErpHrmTimeTimesheet> {
