          : [{ created_at: "desc" as const }, { id: "desc" as const }]
  ) satisfies Prisma.erp_hrm_time_projectsOrderByWithRelationInput[];
  const data = await MyGlobal.prisma.erp_hrm_time_projects.findMany({
